const config=window.RESHMA_CONFIG||{};const hasConfig=Boolean(config.supabaseUrl&&config.supabasePublishableKey);let supabase=null;let isSignUp=false;if(hasConfig){const{createClient}=await import("https://esm.sh/@supabase/supabase-js@2");supabase=createClient(config.supabaseUrl,config.supabasePublishableKey)}const grid=document.querySelector("#productGrid"),statusEl=document.querySelector("#catalogueStatus");document.querySelector("#year").textContent=new Date().getFullYear();function esc(v=""){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}function card(p){const price=Number(p.retail_price)>0?new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(p.retail_price):"Ask for price";return `<article class="product-card">${p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy">`:'<div class="product-art plaid plum"></div>'}<div class="product-info"><span class="tag">${esc(p.categories?.name||"RESHMA COLLECTION")}</span><h3>${esc(p.name)}</h3><p>${esc(p.description||p.design||"Made for everyday comfort")}</p><strong>${price}</strong></div></article>`}async function loadProducts(){if(!supabase){statusEl.textContent="The live catalogue is temporarily unavailable. Please contact us for current designs.";grid.innerHTML='<div class="catalogue-empty"><strong>Our collection is being prepared.</strong><span>Contact us for current designs, availability and prices.</span><a href="#contact">Make an enquiry ↗</a></div>';document.querySelector("#productCount").textContent="COMING SOON";return}statusEl.textContent="Loading catalogue…";const{data,error}=await supabase.from("products").select("id,name,description,design,image_url,retail_price,categories(name)").eq("is_active",true).order("created_at",{ascending:false});if(error){statusEl.textContent="Catalogue is temporarily unavailable. Please contact us for current designs.";grid.innerHTML='<div class="catalogue-empty"><strong>We are preparing the live collection.</strong><span>Please contact us for current designs and availability.</span><a href="#contact">Make an enquiry ↗</a></div>';console.error(error.message);return}if(!data?.length){statusEl.textContent="";grid.innerHTML='<div class="catalogue-empty"><strong>Our first collection is being prepared.</strong><span>Contact us for current designs, availability and prices.</span><a href="#contact">Make an enquiry ↗</a></div>';document.querySelector("#productCount").textContent="COMING SOON";return}grid.innerHTML=data.map(card).join("");document.querySelector("#productCount").textContent=data.length+" designs";statusEl.remove()}if(!window.RESHMA_ERP_ONLY)loadProducts();document.querySelector("#accountBtn").addEventListener("click",()=>document.querySelector("#accountDialog").showModal());document.querySelector("#authToggle").addEventListener("click",()=>{isSignUp=!isSignUp;document.querySelector("#authTitle").textContent=isSignUp?"Create account":"Sign in";document.querySelector("#authSubmit").textContent=isSignUp?"Create account":"Sign in";document.querySelector("#authToggle").textContent=isSignUp?"Already registered? Sign in":"New here? Create an account"});document.querySelector("#authForm").addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(e.currentTarget),msg=document.querySelector("#authStatus");if(!supabase){msg.textContent="Sign-in will be available after Supabase keys are configured.";return}msg.textContent="Please wait…";const r=isSignUp?await supabase.auth.signUp({email:f.get("email"),password:f.get("password")}):await supabase.auth.signInWithPassword({email:f.get("email"),password:f.get("password")});if(r.error){msg.textContent=r.error.message;return}msg.textContent=isSignUp?"Account created. Check your email if confirmation is enabled.":"You are signed in.";if(!isSignUp){document.querySelector("#accountBtn").textContent="My account";setTimeout(()=>document.querySelector("#accountDialog").close(),900)}});if(supabase)supabase.auth.getUser().then(({data})=>{if(data.user)document.querySelector("#accountBtn").textContent="My account"});document.querySelector("#enquiryForm").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),status=document.querySelector("#enquiryStatus"),submit=form.querySelector('button[type="submit"]');if(!supabase){status.textContent="We couldn't connect to the enquiry service. Please try again later.";return}const name=String(f.get("name")||"").trim(),phone=String(f.get("phone")||"").trim(),type=String(f.get("type")||"Retail purchase"),message=String(f.get("message")||"").trim();if(name.length<2||phone.length<7){status.textContent="Please enter your name and a valid phone number.";return}submit.disabled=true;submit.textContent="Saving your enquiry…";status.textContent="";try{const{error}=await supabase.from("customer_enquiries").insert({customer_name:name,phone,enquiry_type:type,message:message||null});if(error)throw error;form.reset();status.textContent="Thank you! Your enquiry has been saved. Our team will contact you soon.";status.scrollIntoView({behavior:"smooth",block:"nearest"})}catch(error){console.error("Enquiry submission failed:",error);status.textContent="We couldn't save your enquiry right now. Please try again in a moment."}finally{submit.disabled=false;submit.innerHTML='Send your enquiry <span>↗</span>'}});
const adminPanel=document.querySelector("#adminInbox"),productManager=document.querySelector("#productManager"),adminLink=document.querySelector("#enquiriesBtn"),adminStatus=document.querySelector("#adminStatus"),enquiryList=document.querySelector("#enquiryList");
let adminRows=[],adminReady=false;
const statusLabels={new:"New",contacted:"Contacted",in_progress:"In progress",converted:"Converted",closed:"Closed"};
function dateLabel(v){return new Intl.DateTimeFormat("en-IN",{dateStyle:"medium",timeStyle:"short"}).format(new Date(v))}
function csvCell(v){return '"'+String(v??"").replace(/"/g,'""')+'"'}
function renderAdminRows(){
 const term=(document.querySelector("#enquirySearch").value||"").trim().toLowerCase(),filter=document.querySelector("#enquiryFilter").value;
 const rows=adminRows.filter(r=>(filter==="all"||r.status===filter)&&(!term||[r.customer_name,r.phone,r.message,r.enquiry_type].some(v=>String(v||"").toLowerCase().includes(term))));
 enquiryList.innerHTML=rows.length?rows.map(r=>`<article class="enquiry-card"><div class="enquiry-card-main"><div class="enquiry-card-head"><span class="enquiry-type">${esc(r.enquiry_type)}</span><time>${esc(dateLabel(r.created_at))}</time></div><h3>${esc(r.customer_name)}</h3><a class="enquiry-phone" href="tel:${esc(r.phone.replace(/[^+0-9]/g,""))}">${esc(r.phone)}</a><p>${esc(r.message||"No additional message provided.")}</p></div><div class="enquiry-card-side"><span class="status-pill status-${esc(r.status)}">${esc(statusLabels[r.status]||r.status)}</span><label>Update status<select class="status-update" aria-label="Update status for ${esc(r.customer_name)}" data-id="${esc(r.id)}">${Object.entries(statusLabels).map(([k,v])=>`<option value="${k}" ${r.status===k?"selected":""}>${v}</option>`).join("")}</select></label></div></article>`).join(""):'<div class="admin-empty">No enquiries match this view yet.</div>';
 document.querySelector("#metricTotal").textContent=adminRows.length;
 document.querySelector("#metricNew").textContent=adminRows.filter(r=>r.status==="new").length;
 document.querySelector("#metricProgress").textContent=adminRows.filter(r=>r.status==="in_progress").length;
 document.querySelector("#metricConverted").textContent=adminRows.filter(r=>r.status==="converted").length;
}
async function checkAdmin(){
 if(!supabase)return;
 const{data:{user}}=await supabase.auth.getUser();
 if(!user){adminReady=false;adminLink.hidden=true;adminPanel.hidden=true;productManager.hidden=true;document.querySelector("#signOutBtn").hidden=true;return}
 document.querySelector("#signOutBtn").hidden=false;
 const{data:profile,error}=await supabase.from("profiles").select("role").eq("id",user.id).maybeSingle();
 adminReady=!error&&profile?.role==="admin";
 adminLink.hidden=!adminReady;
 if(!adminReady){adminPanel.hidden=true;productManager.hidden=true;return}
 adminPanel.hidden=false;productManager.hidden=false;await Promise.all([loadEnquiries(),loadAdminProducts()]);
}
async function loadEnquiries(){
 if(!adminReady)return;
 adminStatus.textContent="Loading enquiries…";
 const{data,error}=await supabase.from("customer_enquiries").select("id,customer_name,phone,enquiry_type,message,status,created_at").order("created_at",{ascending:false}).limit(200);
 if(error){adminStatus.textContent="Unable to load enquiries. Please refresh your session and try again.";console.error("Admin enquiry load failed:",error);return}
 adminRows=data||[];adminStatus.textContent=adminRows.length===200?"Showing the latest 200 enquiries.":adminRows.length+" enquiries loaded.";renderAdminRows();
}
adminLink.addEventListener("click",()=>{adminPanel.hidden=false;adminPanel.scrollIntoView({behavior:"smooth",block:"start"})});
document.querySelector("#refreshEnquiries").addEventListener("click",loadEnquiries);
document.querySelector("#enquirySearch").addEventListener("input",renderAdminRows);
document.querySelector("#enquiryFilter").addEventListener("change",renderAdminRows);
enquiryList.addEventListener("change",async e=>{
 const select=e.target.closest(".status-update");if(!select||!adminReady)return;
 const id=select.dataset.id,next=select.value;select.disabled=true;
 const{data,error}=await supabase.from("customer_enquiries").update({status:next}).eq("id",id).select("id,status").single();
 if(error){adminStatus.textContent="Status update failed. Please refresh and try again.";console.error(error);select.disabled=false;return}
 const row=adminRows.find(r=>r.id===id);if(row)row.status=data.status;adminStatus.textContent="Enquiry status updated.";renderAdminRows();
});
document.querySelector("#exportEnquiries").addEventListener("click",()=>{
 if(!adminReady)return;
 const cols=["created_at","customer_name","phone","enquiry_type","message","status"];
 const csv=[cols.join(","),...adminRows.map(r=>cols.map(k=>csvCell(r[k])).join(","))].join("\r\n");
 const url=URL.createObjectURL(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"})),a=document.createElement("a");a.href=url;a.download="reshma-textiles-enquiries.csv";a.click();URL.revokeObjectURL(url);
});
document.querySelector("#signOutBtn").addEventListener("click",async()=>{
 const{error}=await supabase.auth.signOut();if(error){document.querySelector("#authStatus").textContent=error.message;return}
 document.querySelector("#accountBtn").textContent="Account ↗";document.querySelector("#authStatus").textContent="You are signed out.";document.querySelector("#signOutBtn").hidden=true;adminLink.hidden=true;adminPanel.hidden=true;
});

const productForm=document.querySelector("#productForm"),adminProductList=document.querySelector("#adminProductList"),productAdminStatus=document.querySelector("#productAdminStatus");
let adminProducts=[];
function slugify(v){return String(v||"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")}
async function loadAdminProducts(){
 if(!adminReady)return;
 productAdminStatus.textContent="Loading products…";
 const{data,error}=await supabase.from("products").select("id,name,slug,sku,fabric,design,description,image_url,retail_price,wholesale_price,min_wholesale_qty,is_active,created_at").order("created_at",{ascending:false}).limit(200);
 if(error){productAdminStatus.textContent="Could not load products. Check your admin session.";console.error(error);return}
 adminProducts=data||[];productAdminStatus.textContent=adminProducts.length+" products loaded.";
 adminProductList.innerHTML=adminProducts.length?adminProducts.map(p=>'<article class="admin-product-card"><div><span class="status-pill '+(p.is_active?"status-converted":"status-closed")+'">'+(p.is_active?"Published":"Draft")+'</span><h3>'+esc(p.name)+'</h3><p>'+esc([p.sku,p.fabric,p.design].filter(Boolean).join(" · ")||"No product code or details")+'</p><small>Retail ₹'+Number(p.retail_price||0).toLocaleString("en-IN")+' · Wholesale ₹'+Number(p.wholesale_price||0).toLocaleString("en-IN")+' · Min. '+esc(p.min_wholesale_qty)+' pcs</small></div><div class="admin-product-actions"><button class="text-link" type="button" data-product-edit="'+esc(p.id)+'">Edit</button><button class="text-link" type="button" data-product-toggle="'+esc(p.id)+'">'+(p.is_active?"Unpublish":"Publish")+'</button></div></article>').join(""):'<div class="admin-empty">No products added yet. Use the form above to create your first product.</div>';
}
function resetProductForm(){productForm.reset();productForm.elements.id.value="";productForm.elements.retail_price.value="0";productForm.elements.wholesale_price.value="0";productForm.elements.min_wholesale_qty.value="10";document.querySelector("#saveProductBtn").textContent="Save product";document.querySelector("#cancelProductEdit").hidden=true}
productForm.addEventListener("submit",async e=>{
 e.preventDefault();if(!adminReady)return;
 const f=new FormData(productForm),id=String(f.get("id")||""),name=String(f.get("name")||"").trim(),sku=String(f.get("sku")||"").trim();
 const payload={name,slug:slugify(name)+(sku?"-"+slugify(sku):""),sku:sku||null,fabric:String(f.get("fabric")||"").trim()||null,design:String(f.get("design")||"").trim()||null,description:String(f.get("description")||"").trim()||null,image_url:String(f.get("image_url")||"").trim()||null,retail_price:Number(f.get("retail_price")),wholesale_price:Number(f.get("wholesale_price")),min_wholesale_qty:Number(f.get("min_wholesale_qty")),is_active:f.get("is_active")==="on"};
 if(!name||![payload.retail_price,payload.wholesale_price].every(v=>Number.isFinite(v)&&v>=0)||!Number.isInteger(payload.min_wholesale_qty)||payload.min_wholesale_qty<1){productAdminStatus.textContent="Check the product name, prices and minimum quantity.";return}
 const submit=document.querySelector("#saveProductBtn");submit.disabled=true;productAdminStatus.textContent=id?"Updating product…":"Saving product…";
 const result=id?await supabase.from("products").update(payload).eq("id",id).select("id").single():await supabase.from("products").insert(payload).select("id").single();
 submit.disabled=false;
 if(result.error){productAdminStatus.textContent="Could not save product: "+result.error.message;return}
 resetProductForm();productAdminStatus.textContent="Product saved.";await Promise.all([loadAdminProducts(),loadProducts()]);
});
adminProductList.addEventListener("click",async e=>{
 const edit=e.target.closest("[data-product-edit]"),toggle=e.target.closest("[data-product-toggle]");
 if(edit){const p=adminProducts.find(x=>x.id===edit.dataset.productEdit);if(!p)return;for(const k of ["id","name","sku","fabric","design","description","image_url","retail_price","wholesale_price","min_wholesale_qty"])productForm.elements[k].value=p[k]??"";productForm.elements.is_active.checked=p.is_active;document.querySelector("#saveProductBtn").textContent="Update product";document.querySelector("#cancelProductEdit").hidden=false;productForm.scrollIntoView({behavior:"smooth",block:"start"});return}
 if(toggle){const p=adminProducts.find(x=>x.id===toggle.dataset.productToggle);if(!p||!adminReady)return;toggle.disabled=true;const{error}=await supabase.from("products").update({is_active:!p.is_active}).eq("id",p.id);if(error){productAdminStatus.textContent="Could not change publish status: "+error.message;toggle.disabled=false;return}productAdminStatus.textContent=p.is_active?"Product unpublished.":"Product published.";await Promise.all([loadAdminProducts(),loadProducts()]);}
});
document.querySelector("#cancelProductEdit").addEventListener("click",resetProductForm);
document.querySelector("#refreshProducts").addEventListener("click",loadAdminProducts);

if(supabase)supabase.auth.onAuthStateChange((event)=>{if(["SIGNED_IN","INITIAL_SESSION","TOKEN_REFRESHED"].includes(event))setTimeout(checkAdmin,0);if(event==="SIGNED_OUT")checkAdmin()});


// RESHMA TEXTILES BUSINESS WORKSPACE
const businessWorkspace=document.querySelector("#businessWorkspace");
const businessBtn=document.querySelector("#businessBtn");
const money=v=>new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:2}).format(Number(v||0));
const val=(form,key)=>String(new FormData(form).get(key)||"").trim();
const setStatus=(id,msg)=>{const el=document.getElementById(id);if(el)el.textContent=msg};
const fillSelect=(id,rows,label,placeholder="Select…")=>{const el=document.getElementById(id);if(!el)return;const old=el.value;el.innerHTML='<option value="">'+esc(placeholder)+'</option>'+rows.map(r=>'<option value="'+esc(r.id)+'">'+esc(label(r))+'</option>').join("");if(rows.some(r=>r.id===old))el.value=old};
let ops={materials:[],suppliers:[],products:[],variants:[],batches:[],customers:[],invoices:[],purchaseOrders:[],operations:[],expenses:[],supplierBills:[],dispatches:[],goodsReceipts:[],auditEvents:[],quotations:[],settings:null,invoiceLines:[]};
async function opsRows(table,select="*"){const {data,error}=await supabase.from(table).select(select).order("created_at",{ascending:false}).limit(500);if(error)throw error;return data||[]}
function opsTable(el,rows,columns){const node=document.getElementById(el);if(!node)return;node.innerHTML=rows.length?'<div class="ops-table-wrap"><table class="ops-table"><thead><tr>'+columns.map(c=>'<th>'+esc(c.label)+'</th>').join("")+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+columns.map(c=>'<td>'+esc(c.render?c.render(r):r[c.key]??"—")+'</td>').join("")+'</tr>').join("")+'</tbody></table></div>':'<p class="ops-muted">No records yet. Add your first record above.</p>'}
function opsSelects(){
 fillSelect("receiptSupplier",ops.suppliers,s=>s.name);fillSelect("poSupplier",ops.suppliers,s=>s.name);fillSelect("poMaterial",ops.materials,m=>m.name+" ("+m.unit+")");fillSelect("receiptPO",ops.purchaseOrders||[],p=>p.po_number+" · "+(ops.suppliers.find(s=>s.id===p.supplier_id)?.name||"Supplier"),"Direct receipt / no PO");fillSelect("receiptMaterial",ops.materials,m=>m.name+" ("+m.unit+")");
 fillSelect("variantProduct",ops.products,p=>p.name);fillSelect("batchProduct",ops.products,p=>p.name);
 fillSelect("batchVariant",ops.variants,v=>v.sku+" · "+(v.color||"")+"/"+(v.size||""));
 fillSelect("issueBatch",ops.batches,b=>b.batch_number);fillSelect("costBatch",ops.batches,b=>b.batch_number);fillSelect("completeBatch",ops.batches,b=>b.batch_number);
 fillSelect("issueMaterial",ops.materials,m=>m.name+" · stock "+m.current_stock+" "+m.unit);
 fillSelect("invoiceCustomer",ops.customers,c=>c.name+" · "+c.customer_type,"Use customer name below");
 fillSelect("invoiceVariant",ops.variants.filter(v=>v.is_active),v=>v.sku+" · "+(v.color||"")+" "+(v.size||"")+" · stock "+v.stock_qty);
 fillSelect("operationBatch",ops.batches,b=>b.batch_number);
 fillSelect("operationSupplier",ops.suppliers,x=>x.name,"No supplier (in-house)");
 fillSelect("expenseSupplier",ops.suppliers,x=>x.name,"Not linked");
 fillSelect("expenseBatch",ops.batches,x=>x.batch_number,"Not linked");
 fillSelect("supplierBillSupplier",ops.suppliers,x=>x.name);
 fillSelect("supplierBillPO",ops.purchaseOrders||[],x=>x.po_number,"Not linked");
 fillSelect("supplierBillGRN",ops.goodsReceipts||[],x=>x.grn_number,"Not linked");
 fillSelect("dispatchInvoice",ops.invoices.filter(x=>x.status==="issued"),x=>(x.invoice_number||"Invoice")+" · "+x.customer_name);
 fillSelect("quoteCustomer",ops.customers,x=>x.name+" · "+x.customer_type,"Use customer name below");
 fillSelect("quoteVariant",ops.variants.filter(v=>v.is_active),v=>v.sku+" · "+(v.color||"")+" "+(v.size||"")+" · stock "+v.stock_qty);
}
async function loadOps(){
 if(!supabase||!adminReady)return;
 setStatus("opsStatus","Loading business records…");
 try{
 const [materials,suppliers,products,variants,batches,customers,invoices,purchaseOrders,operations,expenses,supplierBills,dispatches,goodsReceipts,auditEvents,quotations,settings]=await Promise.all([
 opsRows("raw_materials"),opsRows("suppliers"),opsRows("products","id,name,sku,is_active,created_at"),opsRows("product_variants"),opsRows("production_batches"),opsRows("business_customers"),opsRows("sales_invoices"),opsRows("purchase_orders"),opsRows("production_batch_operations"),opsRows("expenses"),opsRows("supplier_bills"),opsRows("invoice_dispatches"),opsRows("goods_receipts"),opsRows("erp_audit_events"),opsRows("sales_quotations"),supabase.from("business_settings").select("*").eq("id",true).maybeSingle()
 ]);
 if(settings.error)throw settings.error;
 ops={...ops,materials,suppliers,products,variants,batches,customers,invoices,purchaseOrders,operations,expenses,supplierBills,dispatches,goodsReceipts,auditEvents,quotations,settings:settings.data};
 opsSelects();renderOps();loadInvoiceLines();
 setStatus("opsStatus","Live database connected · "+materials.length+" materials · "+suppliers.length+" suppliers · "+invoices.length+" invoices. No sample transactions are present.");
 }catch(e){console.error("Business workspace:",e);setStatus("opsStatus","Could not load business records: "+e.message+" · Check admin access and refresh.");}
}
function renderOps(){
 document.querySelector("#opsMetricMaterials").textContent=ops.materials.length;
 document.querySelector("#opsMetricSuppliers").textContent=ops.suppliers.length;
 document.querySelector("#opsMetricBatches").textContent=ops.batches.filter(b=>!["completed","cancelled"].includes(b.status)).length;
 document.querySelector("#opsMetricInvoices").textContent=ops.invoices.filter(i=>i.status==="issued").length;
 document.querySelector("#opsMetricStock").textContent=ops.variants.reduce((n,v)=>n+Number(v.stock_qty||0),0).toLocaleString("en-IN");
 document.querySelector("#opsMetricDue").textContent=money(ops.invoices.filter(i=>i.status==="issued").reduce((n,i)=>n+Number(i.balance_due||0),0));
 document.querySelector("#opsLowStock").innerHTML=ops.materials.filter(m=>Number(m.current_stock)<=Number(m.reorder_level)).map(m=>'<p>'+esc(m.name)+' — '+esc(m.current_stock)+' '+esc(m.unit)+' (reorder at '+esc(m.reorder_level)+')</p>').join("")||'<p class="ops-muted">No low-stock items, or no materials have been registered.</p>';
 opsTable("materialRows",ops.materials,[{key:"name",label:"Material"},{key:"current_stock",label:"Stock"},{key:"unit",label:"Unit"},{key:"reorder_level",label:"Reorder at"},{key:"unit_cost",label:"Unit cost",render:r=>money(r.unit_cost)}]);
 opsTable("purchaseOrderRows",ops.purchaseOrders||[],[{key:"po_number",label:"PO number"},{key:"status",label:"Status"},{key:"order_date",label:"Order date"},{key:"total_amount",label:"Total",render:r=>money(r.total_amount)}]);
 opsTable("supplierRows",ops.suppliers,[{key:"name",label:"Supplier"},{key:"phone",label:"Phone"},{key:"city",label:"City"},{key:"gstin",label:"GSTIN"}]);
 opsTable("variantRows",ops.variants,[{key:"sku",label:"SKU"},{key:"color",label:"Colour"},{key:"size",label:"Size"},{key:"stock_qty",label:"Stock"},{key:"retail_price",label:"Retail",render:r=>money(r.retail_price)}]);
 opsTable("batchRows",ops.batches,[{key:"batch_number",label:"Batch"},{key:"status",label:"Status"},{key:"planned_quantity",label:"Planned"},{key:"accepted_quantity",label:"Accepted"},{key:"cost_per_accepted_unit",label:"Cost / piece",render:r=>r.cost_per_accepted_unit?money(r.cost_per_accepted_unit):"—"}]);
 opsTable("customerRows",ops.customers,[{key:"name",label:"Customer"},{key:"customer_type",label:"Type"},{key:"phone",label:"Phone"},{key:"state",label:"State"}]);
 renderInvoices();
 const issued=ops.invoices.filter(x=>x.status==="issued");
 document.querySelector("#financeSales").textContent=money(issued.reduce((n,x)=>n+Number(x.grand_total||0),0));
 document.querySelector("#financeReceivables").textContent=money(issued.reduce((n,x)=>n+Number(x.balance_due||0),0));
 document.querySelector("#financePayables").textContent=money(ops.supplierBills.filter(x=>x.status==="posted").reduce((n,x)=>n+Math.max(0,Number(x.total_amount||0)-Number(x.amount_paid||0)),0));
 document.querySelector("#financeExpenses").textContent=money(ops.expenses.reduce((n,x)=>n+Number(x.amount||0),0));
 document.querySelector("#operationRows").innerHTML=ops.operations.length?ops.operations.map(o=>'<article class="ops-invoice-card"><div><b>'+esc(o.operation_name)+'</b><p>'+esc(o.execution_mode==='job_work'?'Job-work · '+(ops.suppliers.find(x=>x.id===o.supplier_id)?.name||'Supplier'):'In-house')+' · Batch '+esc(ops.batches.find(x=>x.id===o.batch_id)?.batch_number||'')+' · '+esc(o.status)+'</p><small>Planned '+o.planned_quantity+' · completed '+o.completed_quantity+' · agreed '+money(o.agreed_cost)+' · actual '+money(o.actual_cost)+'</small></div><div class="ops-invoice-actions">'+(o.status==='planned'?'<button type="button" class="btn btn-light" data-start-operation="'+o.id+'">Start</button>':'')+(o.status==='in_progress'?'<button type="button" class="btn btn-dark" data-complete-operation="'+o.id+'">Complete stage</button>':'')+(o.status==='planned'||o.status==='in_progress'?'<button type="button" class="text-link" data-cancel-operation="'+o.id+'">Cancel</button>':'')+'</div></article>').join(""):'<p class="ops-muted">No production operations added yet.</p>';
 document.querySelector("#quotationRows").innerHTML=ops.quotations.length?ops.quotations.map(q=>'<article class="ops-invoice-card"><div><b>'+esc(q.quotation_number)+'</b><p>'+esc(q.customer_name)+' · '+esc(q.quotation_date)+' · '+esc(q.status)+'</p><strong>'+money(q.grand_total)+'</strong><small>Valid until '+esc(q.valid_until||'—')+'</small></div><div class="ops-invoice-actions">'+(q.status==='draft'?'<button type="button" class="btn btn-light" data-quote-status="sent" data-quote-id="'+q.id+'">Mark sent</button>':'')+(q.status==='sent'?'<button type="button" class="btn btn-light" data-quote-status="accepted" data-quote-id="'+q.id+'">Accept</button><button type="button" class="text-link" data-quote-status="rejected" data-quote-id="'+q.id+'">Reject</button>':'')+'</div></article>').join(""):'<p class="ops-muted">No quotations created yet.</p>';
 opsTable("expenseRows",ops.expenses,[{key:"expense_date",label:"Date"},{key:"category",label:"Category"},{key:"description",label:"Description"},{key:"amount",label:"Amount",render:r=>money(r.amount)},{key:"payment_method",label:"Method"}]);
 opsTable("dispatchRows",ops.dispatches,[{key:"dispatch_date",label:"Dispatch date"},{key:"carrier",label:"Carrier"},{key:"tracking_number",label:"Tracking"},{key:"status",label:"Status"}]);
 opsTable("auditRows",(ops.auditEvents||[]).slice(0,100),[{key:"created_at",label:"When"},{key:"event_type",label:"Action"},{key:"entity_name",label:"Record type"},{key:"entity_id",label:"Record ID"},{key:"actor_id",label:"User"},{key:"changed_fields",label:"Changed fields",render:r=>(r.changed_fields||[]).join(", ")}]);
 const billBox=document.querySelector("#supplierBillRows");
 billBox.innerHTML=ops.supplierBills.length?ops.supplierBills.map(b=>'<article class="ops-invoice-card"><div><b>'+esc(b.bill_number)+'</b><p>'+esc(ops.suppliers.find(x=>x.id===b.supplier_id)?.name||"Supplier")+' · '+esc(b.bill_date)+' · '+esc(b.payment_status)+'</p><strong>'+money(b.total_amount)+'</strong><small>Paid '+money(b.amount_paid)+' · Due '+money(Math.max(0,Number(b.total_amount)-Number(b.amount_paid)))+'</small></div><div class="ops-invoice-actions">'+(b.status==="posted"&&Number(b.total_amount)>Number(b.amount_paid)?'<button type="button" class="btn btn-light" data-pay-supplier-bill="'+b.id+'">Record payment</button>':'')+'</div></article>').join(""):'<p class="ops-muted">No supplier bills recorded.</p>';
 const rawValue=ops.materials.reduce((n,m)=>n+Number(m.current_stock||0)*Number(m.unit_cost||0),0);
 const finishedRetail=ops.variants.reduce((n,v)=>n+Number(v.stock_qty||0)*Number(v.retail_price||0),0);
 const productionCost=ops.batches.reduce((n,b)=>n+Number(b.total_material_cost||0)+Number(b.labour_cost||0)+Number(b.overhead_cost||0),0);
 document.querySelector("#financeReportRows").innerHTML='<div class="ops-row"><b>Raw-material stock value</b><span>'+money(rawValue)+'</span></div><div class="ops-row"><b>Finished-goods retail value (indicative)</b><span>'+money(finishedRetail)+'</span></div><div class="ops-row"><b>Recorded production cost</b><span>'+money(productionCost)+'</span></div><div class="ops-row"><b>Issued sales</b><span>'+money(issued.reduce((n,x)=>n+Number(x.grand_total||0),0))+'</span></div><div class="ops-row"><b>Recorded expenses</b><span>'+money(ops.expenses.reduce((n,x)=>n+Number(x.amount||0),0))+'</span></div>';
}
async function loadInvoiceLines(){const box=document.querySelector("#invoiceLineRows");if(!box)return;box.innerHTML=ops.invoiceLines.length?ops.invoiceLines.map((l,i)=>'<div class="ops-invoice-line"><span>'+esc(l.product_name)+' · '+l.quantity+' × '+money(l.unit_price)+' · GST '+l.gst_rate+'% · '+money(l.line_total)+'</span><button type="button" data-remove-line="'+i+'" class="text-link">Remove</button></div>').join(""):'<p class="ops-muted">No invoice lines added yet.</p>'}
function renderInvoices(){const box=document.querySelector("#invoiceRows");if(!box)return;box.innerHTML=ops.invoices.length?ops.invoices.map(i=>'<article class="ops-invoice-card"><div><b>'+esc(i.invoice_number||"DRAFT · "+i.id.slice(0,8))+'</b><p>'+esc(i.customer_name)+' · '+esc(i.invoice_date)+' · '+esc(i.status)+'</p><strong>'+money(i.grand_total)+'</strong><small>Paid '+money(i.amount_paid)+' · Due '+money(i.balance_due)+'</small></div><div class="ops-invoice-actions">'+(i.status==="draft"?'<button type="button" class="btn btn-dark" data-issue-invoice="'+i.id+'">Issue invoice</button>':'')+(i.status==="issued"&&Number(i.balance_due)>0?'<button type="button" class="btn btn-light" data-pay-invoice="'+i.id+'">Record payment</button><button type="button" class="text-link" data-print-invoice="'+i.id+'">Print</button>':'')+'</div></article>').join(""):'<p class="ops-muted">No invoices yet. Create a draft above.</p>'}
function fillSettings(){const s=ops.settings;if(!s)return;for(const k of ["legal_name","trade_name","gstin","registered_address","state","state_code","phone","email","invoice_prefix","wholesale_invoice_prefix"]) {const el=document.getElementById("setting_"+k);if(el)el.value=s[k]||"";}document.querySelector("#setting_gst_registered").checked=!!s.gst_registered}
function opsError(id,e){console.error(e);setStatus(id,e.message||String(e))}
async function handleOpsForm(id,status,table,mapper,after=loadOps){const form=document.getElementById(id);form.addEventListener("submit",async e=>{e.preventDefault();const btn=form.querySelector('button[type="submit"],button:not([type])');if(btn)btn.disabled=true;try{const {error}=await supabase.from(table).insert(mapper(form));if(error)throw error;form.reset();setStatus(status,"Saved successfully.");await after()}catch(err){opsError(status,err)}finally{if(btn)btn.disabled=false}})}
handleOpsForm("materialForm","materialStatus","raw_materials",f=>({name:val(f,"name"),unit:val(f,"unit"),reorder_level:Number(val(f,"reorder_level")||0),unit_cost:Number(val(f,"unit_cost")||0)}));
handleOpsForm("supplierForm","supplierStatus","suppliers",f=>({name:val(f,"name"),contact_person:val(f,"contact_person")||null,phone:val(f,"phone")||null,email:val(f,"email")||null,gstin:val(f,"gstin")||null,address:val(f,"address")||null,city:val(f,"city")||null,state:val(f,"state")||null,state_code:val(f,"state_code")||null,postal_code:val(f,"postal_code")||null,payment_terms_days:Number(val(f,"payment_terms_days")||0)}));
handleOpsForm("customerForm","customerStatus","business_customers",f=>({customer_type:val(f,"customer_type"),name:val(f,"name"),phone:val(f,"phone")||null,email:val(f,"email")||null,gstin:val(f,"gstin")||null,billing_address:val(f,"billing_address")||null,city:val(f,"city")||null,state:val(f,"state")||null,state_code:val(f,"state_code")||null}));
document.querySelector("#receiptForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const qty=Number(val(f,"received_quantity")),accepted=Number(val(f,"accepted_quantity")),cost=Number(val(f,"unit_cost"));if(qty<=0||accepted<0||accepted>qty||cost<0)throw Error("Check received quantity, accepted quantity and unit cost.");const {error}=await supabase.rpc("create_and_post_goods_receipt",{p_supplier_id:val(f,"supplier_id"),p_purchase_order_id:val(f,"purchase_order_id")||null,p_material_id:val(f,"material_id"),p_supplier_invoice_number:val(f,"supplier_invoice_number")||null,p_received_quantity:qty,p_accepted_quantity:accepted,p_unit_cost:cost,p_notes:null});if(error)throw error;f.reset();setStatus("receiptStatus","Goods receipt posted atomically; accepted quantity added to stock and PO balance updated.");await loadOps()}catch(err){opsError("receiptStatus",err)}});
document.querySelector("#variantForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const p={product_id:val(f,"product_id"),sku:val(f,"sku"),color:val(f,"color")||null,size:val(f,"size")||null,length:val(f,"length")||null,retail_price:Number(val(f,"retail_price")),wholesale_price:Number(val(f,"wholesale_price")),hsn_code:val(f,"hsn_code")||null,gst_rate:val(f,"gst_rate")?Number(val(f,"gst_rate")):0};const {error}=await supabase.from("product_variants").insert(p);if(error)throw error;f.reset();setStatus("variantStatus","Variant created with zero opening stock.");await loadOps()}catch(err){opsError("variantStatus",err)}});
document.querySelector("#batchForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const {error}=await supabase.from("production_batches").insert({batch_number:val(f,"batch_number"),product_id:val(f,"product_id"),output_variant_id:val(f,"variant_id"),planned_quantity:Number(val(f,"planned_quantity")),start_date:val(f,"start_date")||null,notes:val(f,"notes")||null,status:"planned"});if(error)throw error;f.reset();setStatus("batchStatus","Production batch created.");await loadOps()}catch(err){opsError("batchStatus",err)}});
document.querySelector("#issueForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const {error}=await supabase.rpc("issue_production_material",{p_batch_id:val(f,"batch_id"),p_material_id:val(f,"material_id"),p_quantity:Number(val(f,"quantity"))});if(error)throw error;f.reset();setStatus("issueStatus","Material issued; raw stock and batch cost updated.");await loadOps()}catch(err){opsError("issueStatus",err)}});
document.querySelector("#costForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const {error}=await supabase.from("manufacturing_costs").insert({batch_id:val(f,"batch_id"),cost_type:val(f,"cost_type"),description:val(f,"description")||null,amount:Number(val(f,"amount"))});if(error)throw error;f.reset();setStatus("costStatus","Manufacturing cost recorded.");await loadOps()}catch(err){opsError("costStatus",err)}});
document.querySelector("#completeForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const {error}=await supabase.rpc("complete_production_batch",{p_batch_id:val(f,"batch_id"),p_accepted:Number(val(f,"accepted_quantity")),p_rejected:Number(val(f,"rejected_quantity")),p_notes:val(f,"notes")||null});if(error)throw error;f.reset();setStatus("completeStatus","Batch completed; accepted pieces added to finished stock.");await loadOps()}catch(err){opsError("completeStatus",err)}});
document.querySelector("#addInvoiceLine").addEventListener("click",async()=>{try{const id=document.querySelector("#invoiceVariant").value,v=ops.variants.find(x=>x.id===id);if(!v)throw Error("Select a finished-goods variant.");const qty=Number(document.querySelector("#invoiceQty").value),price=Number(document.querySelector("#invoicePrice").value||v.retail_price),rate=Number(document.querySelector("#invoiceGstRate").value||v.gst_rate||0),hsn=document.querySelector("#invoiceHsn").value.trim()||v.hsn_code||"";if(!Number.isInteger(qty)||qty<1||price<0||rate<0||rate>100)throw Error("Check quantity, price and GST rate.");const taxable=qty*price,tax=taxable*rate/100,supply=document.querySelector("#invoiceForm").elements.supply_type.value;ops.invoiceLines.push({product_id:v.product_id,variant_id:v.id,product_name:ops.products.find(p=>p.id===v.product_id)?.name||v.sku,sku:v.sku,hsn_code:hsn||null,quantity:qty,unit:"pcs",unit_price:price,discount_amount:0,taxable_value:taxable,gst_rate:rate,cgst_rate:supply==="intra_state"?rate/2:0,sgst_rate:supply==="intra_state"?rate/2:0,igst_rate:supply==="inter_state"?rate:0,cgst_amount:supply==="intra_state"?tax/2:0,sgst_amount:supply==="intra_state"?tax/2:0,igst_amount:supply==="inter_state"?tax:0,line_total:taxable+tax});loadInvoiceLines()}catch(err){setStatus("invoiceStatus",err.message)}});
document.querySelector("#invoiceLineRows").addEventListener("click",e=>{const b=e.target.closest("[data-remove-line]");if(b){ops.invoiceLines.splice(Number(b.dataset.removeLine),1);loadInvoiceLines()}});
document.querySelector("#invoiceForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{if(!ops.invoiceLines.length)throw Error("Add at least one invoice line.");const customer=ops.customers.find(c=>c.id===val(f,"customer_id"));const supply=val(f,"supply_type"),subtotal=ops.invoiceLines.reduce((n,l)=>n+l.quantity*l.unit_price,0),taxable=ops.invoiceLines.reduce((n,l)=>n+l.taxable_value,0),cgst=ops.invoiceLines.reduce((n,l)=>n+l.cgst_amount,0),sgst=ops.invoiceLines.reduce((n,l)=>n+l.sgst_amount,0),igst=ops.invoiceLines.reduce((n,l)=>n+l.igst_amount,0),tax=cgst+sgst+igst,total=taxable+tax;const {data:inv,error}=await supabase.from("sales_invoices").insert({invoice_type:val(f,"invoice_type"),invoice_date:new Date().toISOString().slice(0,10),customer_id:customer?.id||null,customer_name:customer?.name||val(f,"customer_name"),customer_phone:customer?.phone||null,customer_email:customer?.email||null,customer_gstin:customer?.gstin||null,billing_address:customer?.billing_address||null,place_of_supply:val(f,"place_of_supply"),place_of_supply_code:val(f,"place_of_supply_code"),supply_type:supply,status:"draft",subtotal, taxable_value:taxable,cgst_amount:cgst,sgst_amount:sgst,igst_amount:igst,total_tax:tax,grand_total:total,balance_due:total,created_by:(await supabase.auth.getUser()).data.user.id}).select("id").single();if(error)throw error;const {error:le}=await supabase.from("sales_invoice_items").insert(ops.invoiceLines.map(l=>({...l,invoice_id:inv.id})));if(le)throw le;ops.invoiceLines=[];f.reset();setStatus("invoiceStatus","Draft saved. It will not deduct stock until issued.");await loadOps()}catch(err){opsError("invoiceStatus",err)}});
document.querySelector("#invoiceCustomer").addEventListener("change",()=>{const c=ops.customers.find(x=>x.id===document.querySelector("#invoiceCustomer").value);if(c)document.querySelector("#invoiceForm").elements.customer_name.value=c.name});
document.querySelector("#invoiceVariant").addEventListener("change",()=>{const v=ops.variants.find(x=>x.id===document.querySelector("#invoiceVariant").value);if(v){document.querySelector("#invoicePrice").value=document.querySelector("#invoiceType").value==="wholesale"?v.wholesale_price:v.retail_price;document.querySelector("#invoiceHsn").value=v.hsn_code||"";document.querySelector("#invoiceGstRate").value=v.gst_rate||0}});
document.querySelector("#invoiceType").addEventListener("change",()=>document.querySelector("#invoiceVariant").dispatchEvent(new Event("change")));
document.querySelector("#invoiceRows").addEventListener("click",async e=>{const issue=e.target.closest("[data-issue-invoice]"),pay=e.target.closest("[data-pay-invoice]"),print=e.target.closest("[data-print-invoice]");try{if(issue){if(!confirm("Issue this invoice and deduct finished stock?"))return;const {error}=await supabase.rpc("post_sales_invoice",{p_invoice_id:issue.dataset.issueInvoice});if(error)throw error;setStatus("invoiceStatus","Invoice issued and stock deducted.");await loadOps()}else if(pay){const inv=ops.invoices.find(x=>x.id===pay.dataset.payInvoice),amount=prompt("Payment amount (outstanding "+money(inv.balance_due)+")");if(amount===null)return;const method=prompt("Payment method: cash, upi, bank_transfer, card, cheque or other","upi")||"upi";const {error}=await supabase.rpc("record_invoice_payment",{p_invoice_id:inv.id,p_amount:Number(amount),p_method:method,p_reference:null,p_payment_date:new Date().toISOString().slice(0,10)});if(error)throw error;await loadOps()}else if(print){const inv=ops.invoices.find(x=>x.id===print.dataset.printInvoice);const {data:lines,error}=await supabase.from("sales_invoice_items").select("*").eq("invoice_id",inv.id);if(error)throw error;printInvoice(inv,lines||[])}}catch(err){setStatus("invoiceStatus",err.message);console.error(err)}});
function printInvoice(inv,lines){const s=ops.settings||{},w=window.open("","_blank");if(!w)throw Error("Allow pop-ups to print the invoice.");w.document.write('<html><head><title>'+esc(inv.invoice_number||"Invoice draft")+'</title><style>body{font:14px Arial;padding:35px;color:#222}h1{margin-bottom:4px}table{width:100%;border-collapse:collapse;margin-top:25px}td,th{border:1px solid #ccc;padding:9px;text-align:left}.right{text-align:right}.muted{color:#666}</style></head><body><h1>'+esc(s.trade_name||s.legal_name||"Reshma Textiles")+'</h1><p>'+esc(s.registered_address||"XXXX · registered address pending")+'<br>GSTIN: '+esc(s.gstin||"XXXX")+'</p><hr><h2>'+esc(inv.status==="issued"?"TAX INVOICE":"DRAFT INVOICE")+' · '+esc(inv.invoice_number||"Not issued")+'</h2><p>Date: '+esc(inv.invoice_date)+'<br>Customer: '+esc(inv.customer_name)+'<br>Place of supply: '+esc(inv.place_of_supply||"XXXX")+'</p><table><tr><th>Product</th><th>HSN</th><th>Qty</th><th>Rate</th><th>Taxable</th><th>Total</th></tr>'+lines.map(l=>'<tr><td>'+esc(l.product_name)+'</td><td>'+esc(l.hsn_code||"XXXX")+'</td><td>'+esc(l.quantity)+'</td><td>'+money(l.unit_price)+'</td><td>'+money(l.taxable_value)+'</td><td>'+money(l.line_total)+'</td></tr>').join("")+'</table><h3 class="right">Total: '+money(inv.grand_total)+'</h3><p class="muted">Draft/test values marked XXXX are placeholders and not valid tax particulars.</p><script>window.print()<\/script></body></html>');w.document.close()}
document.querySelector("#settingForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const {error}=await supabase.from("business_settings").upsert({id:true,legal_name:val(f,"legal_name")||null,trade_name:val(f,"trade_name")||null,gst_registered:document.querySelector("#setting_gst_registered").checked,gstin:val(f,"gstin")||null,registered_address:val(f,"registered_address")||null,state:val(f,"state")||null,state_code:val(f,"state_code")||null,phone:val(f,"phone")||null,email:val(f,"email")||null,invoice_prefix:val(f,"invoice_prefix")||"RT",wholesale_invoice_prefix:val(f,"wholesale_invoice_prefix")||"RTW",updated_by:(await supabase.auth.getUser()).data.user.id},{onConflict:"id"});if(error)throw error;setStatus("settingsStatus","Business settings saved.");await loadOps()}catch(err){opsError("settingsStatus",err)}});
document.querySelectorAll("[data-ops-tab]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-ops-tab]").forEach(x=>x.classList.toggle("active",x===b));document.querySelectorAll("[data-ops-panel]").forEach(p=>p.hidden=p.dataset.opsPanel!==b.dataset.opsTab);if(b.dataset.opsTab==="settings")fillSettings()}));
document.querySelector("#refreshOps").addEventListener("click",loadOps);
businessBtn.addEventListener("click",()=>{businessWorkspace.hidden=false;businessWorkspace.scrollIntoView({behavior:"smooth",block:"start"});loadOps()});
async function revealBusinessWorkspace(){if(!supabase)return;const {data:{user}}=await supabase.auth.getUser();if(!user)return;const {data:profile}=await supabase.from("profiles").select("role").eq("id",user.id).maybeSingle();if(profile?.role==="admin")businessBtn.hidden=false;}
if(supabase){supabase.auth.getSession().then(revealBusinessWorkspace);supabase.auth.onAuthStateChange((event)=>{if(["SIGNED_IN","INITIAL_SESSION","TOKEN_REFRESHED"].includes(event))setTimeout(revealBusinessWorkspace,250);if(event==="SIGNED_OUT"){businessBtn.hidden=true;businessWorkspace.hidden=true}})}

document.querySelector("#purchaseOrderForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const qty=Number(val(f,"quantity")),cost=Number(val(f,"unit_cost")),rate=Number(val(f,"tax_rate")||0);if(qty<=0||cost<0||rate<0||rate>100)throw Error("Check quantity, unit cost and GST rate.");const {error}=await supabase.rpc("create_purchase_order",{p_supplier_id:val(f,"supplier_id"),p_po_number:val(f,"po_number")||null,p_order_date:val(f,"order_date")||null,p_expected_date:val(f,"expected_date")||null,p_material_id:val(f,"material_id"),p_quantity:qty,p_unit:val(f,"unit"),p_unit_cost:cost,p_tax_rate:rate,p_notes:val(f,"notes")||null});if(error)throw error;f.reset();setStatus("purchaseOrderStatus","Purchase order and item saved in one database transaction.");await loadOps()}catch(err){opsError("purchaseOrderStatus",err)}});

document.querySelector("#operationForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const mode=val(f,"execution_mode"),supplier=val(f,"supplier_id");if(mode==="job_work"&&!supplier)throw Error("Select a supplier for outsourced job-work.");const {error}=await supabase.from("production_batch_operations").insert({batch_id:val(f,"batch_id"),operation_name:val(f,"operation_name"),execution_mode:mode,supplier_id:mode==="job_work"?supplier:null,planned_quantity:Number(val(f,"planned_quantity")||0),agreed_cost:Number(val(f,"agreed_cost")||0),notes:val(f,"notes")||null});if(error)throw error;f.reset();setStatus("operationStatus","Production stage saved.");await loadOps()}catch(err){opsError("operationStatus",err)}});
document.querySelector("#operationMode").addEventListener("change",e=>{const supplier=document.querySelector("#operationSupplier");supplier.required=e.target.value==="job_work";supplier.disabled=e.target.value!=="job_work";if(e.target.value!=="job_work")supplier.value=""});
document.querySelector("#expenseForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const amount=Number(val(f,"amount"));if(amount<=0)throw Error("Expense amount must be greater than zero.");const {error}=await supabase.from("expenses").insert({expense_date:val(f,"expense_date")||new Date().toISOString().slice(0,10),category:val(f,"category"),description:val(f,"description"),amount,payment_method:val(f,"payment_method"),paid_to:val(f,"paid_to")||null,supplier_id:val(f,"supplier_id")||null,batch_id:val(f,"batch_id")||null,reference_number:val(f,"reference_number")||null,notes:val(f,"notes")||null});if(error)throw error;f.reset();setStatus("expenseStatus","Expense recorded.");await loadOps()}catch(err){opsError("expenseStatus",err)}});
document.querySelector("#supplierBillForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const subtotal=Number(val(f,"subtotal")),tax=Number(val(f,"tax_amount")||0),total=Number(val(f,"total_amount"));if(subtotal<0||tax<0||total<=0||Math.abs(total-subtotal-tax)>0.01)throw Error("Total must equal subtotal plus tax.");const {error}=await supabase.from("supplier_bills").insert({bill_number:val(f,"bill_number"),supplier_id:val(f,"supplier_id"),supplier_invoice_number:val(f,"supplier_invoice_number")||null,bill_date:val(f,"bill_date")||new Date().toISOString().slice(0,10),due_date:val(f,"due_date")||null,purchase_order_id:val(f,"purchase_order_id")||null,goods_receipt_id:val(f,"goods_receipt_id")||null,status:"posted",subtotal,tax_amount:tax,total_amount:total,amount_paid:0,payment_status:"unpaid",notes:val(f,"notes")||null,created_by:(await supabase.auth.getUser()).data.user.id});if(error)throw error;f.reset();setStatus("supplierBillStatus","Supplier bill posted; payable recorded.");await loadOps()}catch(err){opsError("supplierBillStatus",err)}});
document.querySelector("#supplierBillRows").addEventListener("click",async e=>{const b=e.target.closest("[data-pay-supplier-bill]");if(!b)return;const bill=ops.supplierBills.find(x=>x.id===b.dataset.paySupplierBill);if(!bill)return;const due=Number(bill.total_amount)-Number(bill.amount_paid),raw=prompt("Enter payment amount. Outstanding: "+money(due));if(raw===null)return;const amount=Number(raw);if(!Number.isFinite(amount)||amount<=0){setStatus("supplierBillStatus","Enter a valid positive payment.");return;}const method=prompt("Payment method: cash, upi, bank_transfer, card, cheque, other","upi");if(!method)return;try{const {error}=await supabase.rpc("record_supplier_bill_payment",{p_bill_id:bill.id,p_amount:amount,p_method:method,p_reference:null,p_payment_date:new Date().toISOString().slice(0,10)});if(error)throw error;setStatus("supplierBillStatus","Supplier payment recorded.");await loadOps()}catch(err){opsError("supplierBillStatus",err)}});
document.querySelector("#dispatchForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{const {error}=await supabase.from("invoice_dispatches").upsert({invoice_id:val(f,"invoice_id"),dispatch_date:val(f,"dispatch_date")||null,carrier:val(f,"carrier")||null,tracking_number:val(f,"tracking_number")||null,tracking_url:val(f,"tracking_url")||null,status:val(f,"status"),notes:val(f,"notes")||null,created_by:(await supabase.auth.getUser()).data.user.id,updated_at:new Date().toISOString()},{onConflict:"invoice_id"});if(error)throw error;f.reset();setStatus("dispatchStatus","Dispatch details saved.");await loadOps()}catch(err){opsError("dispatchStatus",err)}});

let quotationLines=[];
function renderQuotationLines(){const box=document.querySelector("#quoteLineRows");if(!box)return;box.innerHTML=quotationLines.length?quotationLines.map((x,i)=>'<div class="ops-invoice-line"><span>'+esc(x.product_name)+' · '+x.quantity+' × '+money(x.unit_price)+' · GST '+x.gst_rate+'%</span><button type="button" class="text-link" data-remove-quote-line="'+i+'">Remove</button></div>').join(""):'<p class="ops-muted">No quotation lines added yet.</p>'}
document.querySelector("#quoteVariant").addEventListener("change",()=>{const v=ops.variants.find(x=>x.id===val(document.querySelector("#quotationForm"),"quote_variant")||x.id===document.querySelector("#quoteVariant").value);if(v){document.querySelector("#quotePrice").value=v.retail_price??0;document.querySelector("#quoteGstRate").value=v.gst_rate??0}});
document.querySelector("#addQuoteLine").addEventListener("click",()=>{const id=document.querySelector("#quoteVariant").value,v=ops.variants.find(x=>x.id===id),qty=Number(document.querySelector("#quoteQty").value),price=Number(document.querySelector("#quotePrice").value),rate=Number(document.querySelector("#quoteGstRate").value||0);if(!v||qty<=0||price<0||rate<0||rate>100){setStatus("quotationStatus","Select a product and enter valid quantity, price and GST rate.");return;}const product=ops.products.find(x=>x.id===v.product_id);quotationLines.push({product_id:v.product_id,variant_id:v.id,product_name:product?.name||"Product",sku:v.sku,quantity:qty,unit_price:price,gst_rate:rate,line_total:qty*price*(1+rate/100)});renderQuotationLines();setStatus("quotationStatus","Quote line added.");});
document.querySelector("#quoteLineRows").addEventListener("click",e=>{const b=e.target.closest("[data-remove-quote-line]");if(!b)return;quotationLines.splice(Number(b.dataset.removeQuoteLine),1);renderQuotationLines()});
document.querySelector("#quotationForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;try{if(!quotationLines.length)throw Error("Add at least one product line.");const customer=ops.customers.find(x=>x.id===val(f,"customer_id"));const customerName=customer?.name||val(f,"customer_name");if(!customerName)throw Error("Enter or select a customer.");const subtotal=quotationLines.reduce((n,x)=>n+x.quantity*x.unit_price,0),tax=quotationLines.reduce((n,x)=>n+x.quantity*x.unit_price*x.gst_rate/100,0),total=subtotal+tax;const {data:{user}}=await supabase.auth.getUser();const {data:quote,error}=await supabase.from("sales_quotations").insert({quotation_number:val(f,"quotation_number")||"QT-"+Date.now().toString().slice(-8),customer_id:customer?.id||null,customer_name:customerName,valid_until:val(f,"valid_until")||null,status:"draft",subtotal,tax_amount:tax,grand_total:total,notes:val(f,"notes")||null,created_by:user.id}).select("id").single();if(error)throw error;const lines=quotationLines.map(x=>({...x,quotation_id:quote.id}));const {error:lineError}=await supabase.from("sales_quotation_items").insert(lines);if(lineError)throw lineError;quotationLines=[];f.reset();renderQuotationLines();setStatus("quotationStatus","Quotation saved as draft. No stock has been reserved or deducted.");await loadOps()}catch(err){opsError("quotationStatus",err)}});

document.querySelector("#operationRows").addEventListener("click",async e=>{const start=e.target.closest("[data-start-operation]"),complete=e.target.closest("[data-complete-operation]"),cancel=e.target.closest("[data-cancel-operation]");const b=start||complete||cancel;if(!b)return;const id=b.dataset.startOperation||b.dataset.completeOperation||b.dataset.cancelOperation;try{let payload={};if(start)payload={status:"in_progress",started_at:new Date().toISOString()};if(cancel)payload={status:"cancelled"};if(complete){const op=ops.operations.find(x=>x.id===id),rawQty=prompt("Completed quantity",String(op?.planned_quantity??0));if(rawQty===null)return;const qty=Number(rawQty),rawCost=prompt("Actual operation cost (₹)",String(op?.agreed_cost??0));if(rawCost===null)return;const cost=Number(rawCost);if(!Number.isFinite(qty)||qty<0||qty>Number(op?.planned_quantity)||!Number.isFinite(cost)||cost<0)throw Error("Enter valid completed quantity and actual cost.");payload={status:"completed",completed_quantity:qty,actual_cost:cost,completed_at:new Date().toISOString()}}const {error}=await supabase.from("production_batch_operations").update(payload).eq("id",id);if(error)throw error;await loadOps()}catch(err){opsError("operationStatus",err)}});
document.querySelector("#quotationRows").addEventListener("click",async e=>{const b=e.target.closest("[data-quote-status]");if(!b)return;try{const {error}=await supabase.from("sales_quotations").update({status:b.dataset.quoteStatus,updated_at:new Date().toISOString()}).eq("id",b.dataset.quoteId);if(error)throw error;await loadOps()}catch(err){opsError("quotationStatus",err)}});


// PRIVATE ERP APP SHELL — owner-only entry, PWA install and app navigation
window.RESHMA_ERP_ONLY=true;
const erpLoginGate=document.querySelector("#erpLoginGate");
const erpAppShell=document.querySelector("#erpAppShell");
const erpLoginForm=document.querySelector("#erpLoginForm");
const erpLoginStatus=document.querySelector("#erpLoginStatus");
const erpLoginSubmit=document.querySelector("#erpLoginSubmit");
const erpSidebar=document.querySelector("#erpSidebar");
const erpMount=document.querySelector("#erpContentMount");
if(businessWorkspace&&erpMount)erpMount.appendChild(businessWorkspace);
function erpSignedOut(message=""){
  erpLoginGate.hidden=false;
  erpAppShell.hidden=true;
  businessWorkspace.hidden=true;
  document.querySelector("#erpOwnerEmail").textContent="";
  if(message)erpLoginStatus.textContent=message;
}
async function erpSignedIn(){
  if(!supabase){erpSignedOut("The secure database connection is not configured.");return}
  const {data:{user},error:userError}=await supabase.auth.getUser();
  if(userError||!user){erpSignedOut();return}
  const {data:profile,error}=await supabase.from("profiles").select("role").eq("id",user.id).maybeSingle();
  if(error){erpSignedOut("We could not verify owner permissions. Please check your connection and try again.");return}
  if(profile?.role!=="admin"){
    await supabase.auth.signOut();
    erpSignedOut("This account is not authorized for the owner workspace.");
    return;
  }
  erpLoginGate.hidden=true;
  erpAppShell.hidden=false;
  businessWorkspace.hidden=false;
  document.querySelector("#erpOwnerEmail").textContent=user.email||"Owner";
  document.querySelector("#businessBtn").hidden=false;
  await loadOps();
}
erpLoginForm.addEventListener("submit",async e=>{
  e.preventDefault();
  if(!supabase){erpLoginStatus.textContent="Secure sign-in is unavailable. Please check the application configuration.";return}
  const form=new FormData(erpLoginForm);
  erpLoginSubmit.disabled=true;
  erpLoginSubmit.textContent="Signing in…";
  erpLoginStatus.textContent="";
  const {error}=await supabase.auth.signInWithPassword({email:String(form.get("email")||"").trim(),password:String(form.get("password")||"")});
  erpLoginSubmit.disabled=false;
  erpLoginSubmit.innerHTML='Sign in to ERP <span>↗</span>';
  if(error){erpLoginStatus.textContent=error.message;return}
  await erpSignedIn();
});
document.querySelector("#erpSignOut").addEventListener("click",async()=>{
  const {error}=await supabase.auth.signOut();
  if(error){erpLoginStatus.textContent="Unable to sign out. Please try again.";return}
  erpLoginForm.reset();
  erpSignedOut("You have been signed out securely.");
});
document.querySelectorAll("[data-erp-nav]").forEach(button=>button.addEventListener("click",()=>{
  const target=button.dataset.erpNav;
  document.querySelectorAll("[data-erp-nav]").forEach(item=>item.classList.toggle("active",item===button));
  const tab=document.querySelector('[data-ops-tab="'+target+'"]');
  if(tab)tab.click();
  erpSidebar.classList.remove("is-open");
  window.scrollTo({top:0,behavior:"smooth"});
}));
document.querySelector("#erpMobileMenu").addEventListener("click",()=>erpSidebar.classList.toggle("is-open"));
if(supabase){
  supabase.auth.getSession().then(({data})=>data.session?erpSignedIn():erpSignedOut());
  supabase.auth.onAuthStateChange((event,session)=>{
    if(event==="SIGNED_OUT")erpSignedOut();
    else if(["SIGNED_IN","INITIAL_SESSION","TOKEN_REFRESHED"].includes(event)&&session)setTimeout(erpSignedIn,150);
  });
}else erpSignedOut("Secure sign-in is not configured.");
if("serviceWorker" in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("/sw.js").catch(err=>console.warn("PWA service worker registration failed",err)));
let erpInstallPrompt=null;
window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();erpInstallPrompt=event;const btn=document.querySelector("#erpInstallApp");if(btn)btn.hidden=false});
document.querySelector("#erpInstallApp")?.addEventListener("click",async()=>{if(!erpInstallPrompt)return;erpInstallPrompt.prompt();await erpInstallPrompt.userChoice;erpInstallPrompt=null;document.querySelector("#erpInstallApp").hidden=true});
